// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOrbitron = makeLoadFont('Orbitron');

// Load Google Font Orbitron at module level (handles delayRender/continueRender internally)
const { fontFamily: orbitronFont } = loadOrbitron();



export type SciFiTitleProps = Record<string, any>;

// GLYPHS used for advanced futuristic scrambles
const GLYPHS = "XΔΛ□■▰▱▲▼◆◇○●/\\_-[]{}<>|=+*^!0123456789";

const scrambleText = (text: string, intensity: number, frame: number) => {
  if (intensity === 0) return text;
  
  const chars = text.split("");
  return chars.map((char, index) => {
    if (char === " ") return " ";
    
    const r = random(`scramble-${frame}-${index}`);
    if (r < intensity) {
      const glyphIndex = Math.floor(random(`glyph-${frame}-${index}`) * GLYPHS.length);
      return GLYPHS[glyphIndex];
    }
    return char;
  }).join("");
};

// Slices definition for horizontal digital tearing
const SLICES_CONFIG = [
  { top: 0, bottom: 8, speed: 1.5 },
  { top: 8, bottom: 20, speed: -1.2 },
  { top: 20, bottom: 35, speed: 2.2 },
  { top: 35, bottom: 48, speed: -1.8 },
  { top: 48, bottom: 60, speed: 0.8 },
  { top: 60, bottom: 72, speed: -2.5 },
  { top: 72, bottom: 85, speed: 1.9 },
  { top: 85, bottom: 100, speed: -0.9 },
];

const SciFiTitle: React.FC<SciFiTitleProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 6,
  titleText = "LIFE 2.0",
  secretText = "AI",
  fontSize = 72,
  letterSpacing = 24,
  glitchFrequency = 0.4,
  rgbStrength = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  const totalFrames = durationInSeconds * fps;
  
  // Phase timing markers based on total video length
  const aiStartFrame = Math.floor(totalFrames * 0.3);
  const aiEndFrame = aiStartFrame + Math.floor(fps * 0.5); // exactly 0.5 seconds long
  const resolveStartFrame = Math.floor(totalFrames * 0.6);
  const resolveEndFrame = Math.floor(totalFrames * 0.75);

  // Determine base text and glitch intensity for current frame
  let baseText = titleText;
  let glitchIntensity = 0;

  if (frame < aiStartFrame) {
    baseText = titleText;
    glitchIntensity = interpolate(
      frame,
      [0, aiStartFrame],
      [1.0, 0.4],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
  } else if (frame >= aiStartFrame && frame < aiEndFrame) {
    // Reveal secret word ("AI")
    baseText = secretText;
    // Low glitch, high-frequency subtle flicker for clarity
    glitchIntensity = 0.12 + 0.08 * random(`ai-flicker-${frame}`);
  } else if (frame >= aiEndFrame && frame < resolveStartFrame) {
    baseText = titleText;
    glitchIntensity = interpolate(
      frame,
      [aiEndFrame, resolveStartFrame],
      [0.85, 0.3],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
  } else if (frame >= resolveStartFrame && frame < resolveEndFrame) {
    baseText = titleText;
    glitchIntensity = interpolate(
      frame,
      [resolveStartFrame, resolveEndFrame],
      [0.3, 0.0],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
  } else {
    baseText = titleText;
    glitchIntensity = 0;
  }

  // Adjust letter spacing to expand beautifully during the final resolved phase
  const spacingDelta = interpolate(
    frame,
    [resolveStartFrame, totalFrames],
    [0.8, 1.15],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const currentLetterSpacing = glitchIntensity > 0 
    ? letterSpacing * (0.95 + 0.1 * random(`spacing-${frame}`))
    : letterSpacing * spacingDelta;

  // Resolve background color
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Render horizontal hairline tearing elements during intense glitches
  const lineRand = random(`line-${frame}`);
  const showHairline = glitchIntensity > 0.4 && lineRand > 0.65;
  const hairlineY = (random(`line-y-${frame}`) - 0.5) * height * 0.35;
  const hairlineW = width * 0.25 * random(`line-w-${frame}`);
  const hairlineX = (random(`line-x-${frame}`) - 0.5) * width * 0.15;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Sliced Typography Container */}
      <div
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
        }}
      >
        {SLICES_CONFIG.map((slice, index) => {
          const sliceKey = `slice-${index}`;
          
          // Seeded horizontal and vertical offsets for this slice
          const rx = random(`slice-x-${index}-${frame}`);
          const ry = random(`slice-y-${index}-${frame}`);
          
          const maxDx = width * 0.08 * glitchIntensity * glitchFrequency;
          const maxDy = height * 0.006 * glitchIntensity * glitchFrequency;
          
          const dx = (rx - 0.5) * maxDx * slice.speed;
          const dy = (ry - 0.5) * maxDy;

          // Seeded opacity drop / micro-flicker
          const flickerVal = random(`flicker-${index}-${frame}`);
          let opacity = 1;
          if (glitchIntensity > 0 && flickerVal < glitchIntensity * 0.15) {
            opacity = flickerVal < 0.05 ? 0 : 0.45;
          }

          // Dynamic text scramble per slice to produce fragmented letters
          const scrambled = scrambleText(baseText, glitchIntensity, frame + index * 100);

          // RGB separation offset
          const rgbMaxShift = width * 0.012 * glitchIntensity * rgbStrength;
          const rgbShift = (random(`rgb-${index}-${frame}`) - 0.5) * rgbMaxShift;

          const textStyle: React.CSSProperties = {
            fontFamily: orbitronFont,
            fontSize: `${fontSize}px`,
            fontWeight: 200,
            letterSpacing: `${currentLetterSpacing}px`,
            textTransform: "uppercase",
            lineHeight: 1,
            whiteSpace: "nowrap",
            WebkitFontSmoothing: "antialiased",
            transition: "none",
          };

          return (
            <div
              key={sliceKey}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                clipPath: `inset(${slice.top}% 0% ${100 - slice.bottom}% 0%)`,
                transform: `translate(${dx}px, ${dy}px)`,
                opacity,
                transition: "none",
              }}
            >
              <div
                style={{
                  position: "relative",
                  width: "100%",
                  height: "100%",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {/* Red Channel Shift */}
                {glitchIntensity > 0 && (
                  <div
                    style={{
                      ...textStyle,
                      position: "absolute",
                      color: "#ff3366",
                      transform: `translateX(${-rgbShift}px)`,
                      mixBlendMode: "screen",
                    }}
                  >
                    {scrambled}
                  </div>
                )}

                {/* Cyan Channel Shift */}
                {glitchIntensity > 0 && (
                  <div
                    style={{
                      ...textStyle,
                      position: "absolute",
                      color: "#00ffff",
                      transform: `translateX(${rgbShift}px)`,
                      mixBlendMode: "screen",
                    }}
                  >
                    {scrambled}
                  </div>
                )}

                {/* Base Crisp White / Silver Channel */}
                <div
                  style={{
                    ...textStyle,
                    position: "absolute",
                    color: "#ffffff",
                    mixBlendMode: glitchIntensity > 0 ? "screen" : "normal",
                  }}
                >
                  {scrambled}
                </div>
              </div>
            </div>
          );
        })}

        {/* Digital Hairline Distortion */}
        {showHairline && (
          <div
            style={{
              position: "absolute",
              top: `calc(50% + ${hairlineY}px)`,
              left: `calc(50% + ${hairlineX}px - ${hairlineW / 2}px)`,
              width: `${hairlineW}px`,
              height: "1px",
              backgroundColor: "rgba(255, 255, 255, 0.55)",
              mixBlendMode: "screen",
              transition: "none",
            }}
          />
        )}
      </div>
    </AbsoluteFill>
  );
};

export default SciFiTitle;